<?php
require_once __DIR__ . '/includes/auth.php'; requireLogin(); $userId=(int)$_SESSION['user_id']; $pageTitle='Packages'; $error='';
if($_SERVER['REQUEST_METHOD']==='POST'){ if(!verifyCsrf($_POST['csrf_token']??null))$error='Your session expired.'; else { $result=createInvestment($userId,(int)post('package_id')); if($result['success']){flash('success',$result['message']);redirect(appUrl('package.php'));} $error=$result['message']; } }
$packages=activePackages(); $wallet=getUserWallet($userId); $s=getDB()->prepare('SELECT i.*,p.name FROM investments i JOIN packages p ON p.id=i.package_id WHERE i.user_id=? ORDER BY i.created_at DESC'); $s->execute([$userId]); $investments=$s->fetchAll();
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?= e($pageTitle) ?> - <?= e(APP_NAME) ?></title><link rel="stylesheet" href="assets/css/style.css"><link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.2/css/all.min.css"></head><body><?php include __DIR__.'/includes/header.php'; ?><?php include __DIR__.'/includes/sidebar.php'; ?><main class="main-content"><div class="page-title"><span class="eyebrow">DEMO CAMPAIGNS</span><h1>Choose a package</h1><p class="muted">Wallet balance: <strong><?= formatCurrency($wallet['balance']) ?></strong>. Package rewards are simulated.</p></div><?php if($error): ?><div class="alert error"><?= e($error) ?></div><?php endif; ?><div class="package-grid"><?php foreach($packages as $p): ?><article class="package-card"><span class="package-icon"><i class="fas fa-cube"></i></span><h2><?= e($p['name']) ?></h2><p><?= e($p['description']) ?></p><div class="package-price"><?= formatCurrency($p['price']) ?></div><div class="package-meta"><span><strong><?= formatCurrency($p['daily_profit']) ?></strong> daily</span><span><strong><?= e($p['validity_days']) ?></strong> days</span></div><form method="post"><?= csrfField() ?><input type="hidden" name="package_id" value="<?= e($p['id']) ?>"><button class="btn primary full" type="submit">Activate package</button></form></article><?php endforeach; ?></div><section class="panel"><div class="section-heading"><h2>My packages</h2></div><?php if(!$investments): ?><p class="empty">You have not activated a package yet.</p><?php else: ?><div class="table-wrap"><table><thead><tr><th>Package</th><th>Amount</th><th>Daily reward</th><th>Status</th><th>Ends</th></tr></thead><tbody><?php foreach($investments as $i): ?><tr><td><?= e($i['name']) ?></td><td><?= formatCurrency($i['amount']) ?></td><td><?= formatCurrency($i['daily_profit']) ?></td><td><span class="badge <?= e($i['status']) ?>"><?= e(ucfirst($i['status'])) ?></span></td><td><?= e(formatDate($i['ends_at'])) ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section></main><?php include __DIR__.'/includes/bottom-nav.php'; ?><?php include __DIR__.'/includes/footer.php'; ?><script src="assets/js/app.js"></script></body></html>
